-- Lab-only reviewed legacy checks. Append to the initial migration AFTER inspecting SQL.
ALTER TABLE "engineering"."bom_item_applicabilities" ADD CONSTRAINT "ck_bom_item_applicabilities_version" CHECK ("Version" >= 1);
ALTER TABLE "engineering"."bom_lines" ADD CONSTRAINT "ck_bom_lines_scrap" CHECK ("ScrapOverridePercent" IS NULL OR "ScrapOverridePercent" BETWEEN 0 AND 100);
ALTER TABLE "engineering"."bom_lines" ADD CONSTRAINT "ck_bom_lines_sort" CHECK ("SortOrder" >= 0);
ALTER TABLE "engineering"."bom_lines" ADD CONSTRAINT "ck_bom_lines_usage" CHECK ("UsageQty" > 0);
ALTER TABLE "engineering"."bom_revisions" ADD CONSTRAINT "ck_bom_revisions_base_output" CHECK ("BaseOutputQty" > 0);
ALTER TABLE "engineering"."bom_revisions" ADD CONSTRAINT "ck_bom_revisions_status" CHECK ("Status" IN ('DRAFT','APPROVED','OBSOLETE'));
ALTER TABLE "engineering"."bom_revisions" ADD CONSTRAINT "ck_bom_revisions_version" CHECK ("Version" >= 1);
ALTER TABLE "catalog"."items" ADD CONSTRAINT "ck_items_business_number_format" CHECK (("ItemType" = 'PRODUCT' AND "BusinessNumber" ~ '^PRD-[0-9]{4,}$') OR ("ItemType" = 'PART' AND "BusinessNumber" ~ '^PRT-[0-9]{4,}$') OR ("ItemType" = 'COMPONENT' AND "BusinessNumber" ~ '^CMP-[0-9]{4,}$'));
ALTER TABLE "catalog"."items" ADD CONSTRAINT "ck_items_item_type" CHECK ("ItemType" IN ('PRODUCT','PART','COMPONENT'));
ALTER TABLE "catalog"."items" ADD CONSTRAINT "ck_items_version" CHECK ("Version" >= 1);
ALTER TABLE "catalog"."material_item_profiles" ADD CONSTRAINT "ck_material_profiles_net_weight" CHECK ("NetWeightKg" IS NULL OR "NetWeightKg" >= 0);
ALTER TABLE "catalog"."material_item_profiles" ADD CONSTRAINT "ck_material_profiles_safety_stock" CHECK ("SafetyStockQty" >= 0);
ALTER TABLE "catalog"."material_item_profiles" ADD CONSTRAINT "ck_material_profiles_scrap" CHECK ("DefaultPlanningScrapPercent" BETWEEN 0 AND 100);
ALTER TABLE "catalog"."material_item_profiles" ADD CONSTRAINT "ck_material_profiles_supply_method" CHECK ("SupplyMethod" IN ('BUY','MAKE','OUTSOURCE','HYBRID'));
ALTER TABLE "catalog"."material_item_profiles" ADD CONSTRAINT "ck_material_profiles_thresholds" CHECK ("CriticalDays" >= 0 AND "CriticalDays" <= "SafeStartDays" AND "SafeStartDays" <= "ExcessStartDays");
ALTER TABLE "identity"."users" ADD CONSTRAINT "ck_identity_users_activation_profile" CHECK (NOT "IsActive" OR ("ProfilePhotoObjectKey" IS NOT NULL AND "ProfilePhotoContentType" IS NOT NULL AND "ProfilePhotoSize" > 0));
ALTER TABLE "planning"."mrp_runs" ADD CONSTRAINT "ck_mrp_runs_completeness" CHECK ("Completeness" IN ('COMPLETE','COMPLETE_WITH_WARNINGS','INCOMPLETE'));
ALTER TABLE "planning"."mrp_runs" ADD CONSTRAINT "ck_mrp_runs_horizon" CHECK ("HorizonEndDate" >= "AsOfDate");
ALTER TABLE "planning"."mrp_runs" ADD CONSTRAINT "ck_mrp_runs_number" CHECK ("RunNumber" ~ '^MRP-RUN-[0-9]{6,}$');
ALTER TABLE "planning"."mrp_runs" ADD CONSTRAINT "ck_mrp_runs_purpose" CHECK ("Purpose" IN ('CURRENT','CERTIFIED','PUBLISHED','LEGACY'));
ALTER TABLE "planning"."mrp_runs" ADD CONSTRAINT "ck_mrp_runs_status" CHECK ("Status" IN ('RUNNING','COMPLETED','COMPLETED_WITH_EXCEPTIONS','FAILED'));
ALTER TABLE "planning"."mrp_run_exceptions" ADD CONSTRAINT "ck_mrp_run_exception_severity" CHECK ("Severity" IN ('ERROR','WARNING','INFO'));
ALTER TABLE "planning"."planner_work_items" ADD CONSTRAINT "ck_planner_work_item_status" CHECK ("Status" IN ('OPEN','ACKNOWLEDGED'));
ALTER TABLE "catalog"."products" ADD CONSTRAINT "ck_products_safety_stock" CHECK ("SafetyStockQty" >= 0);
ALTER TABLE "catalog"."products" ADD CONSTRAINT "ck_products_thresholds" CHECK ("CriticalDays" >= 0 AND "CriticalDays" <= "SafeStartDays" AND "SafeStartDays" <= "ExcessStartDays");
ALTER TABLE "reference_data"."currencies" ADD CONSTRAINT "ck_currencies_decimal_precision" CHECK ("DecimalPrecision" >= 0 AND "DecimalPrecision" <= 9);
ALTER TABLE "reference_data"."currencies" ADD CONSTRAINT "ck_currencies_iso_alpha3" CHECK ("Code" ~ '^[A-Z]{3}$' AND "NormalizedCode" = "Code");
ALTER TABLE "reference_data"."currencies" ADD CONSTRAINT "ck_currencies_version" CHECK ("Version" >= 1);
ALTER TABLE "reference_data"."reference_values" ADD CONSTRAINT "ck_reference_values_sort_order" CHECK ("SortOrder" >= 0);
ALTER TABLE "reference_data"."reference_values" ADD CONSTRAINT "ck_reference_values_version" CHECK ("Version" >= 1);
ALTER TABLE "reference_data"."units" ADD CONSTRAINT "ck_units_sort_order" CHECK ("SortOrder" >= 0);
ALTER TABLE "reference_data"."units" ADD CONSTRAINT "ck_units_version" CHECK ("Version" >= 1);
ALTER TABLE "procurement"."sourcing_options" ADD CONSTRAINT "ck_sourcing_options_domestic_fields" CHECK ("RouteScope" <> 'DOMESTIC' OR ("IncotermId" IS NULL AND "ForwarderToShipmentDays" IS NULL AND "DestinationCustomsDays" IS NULL));
ALTER TABLE "procurement"."sourcing_options" ADD CONSTRAINT "ck_sourcing_options_lead_times" CHECK (("SupplierLeadTimeDays" IS NULL OR "SupplierLeadTimeDays" >= 0) AND ("ForwarderToShipmentDays" IS NULL OR "ForwarderToShipmentDays" >= 0) AND ("ShippingPeriodDays" IS NULL OR "ShippingPeriodDays" >= 0) AND ("DestinationCustomsDays" IS NULL OR "DestinationCustomsDays" >= 0));
ALTER TABLE "procurement"."sourcing_options" ADD CONSTRAINT "ck_sourcing_options_moq" CHECK ("MinimumOrderQuantity" IS NULL OR "MinimumOrderQuantity" >= 0);
ALTER TABLE "procurement"."sourcing_options" ADD CONSTRAINT "ck_sourcing_options_preferred_active" CHECK (NOT "IsPreferred" OR "IsActive");
ALTER TABLE "procurement"."sourcing_options" ADD CONSTRAINT "ck_sourcing_options_route_scope" CHECK ("RouteScope" IN ('DOMESTIC','IMPORT'));
ALTER TABLE "procurement"."sourcing_options" ADD CONSTRAINT "ck_sourcing_options_version" CHECK ("Version" >= 1);
ALTER TABLE "procurement"."sourcing_prices" ADD CONSTRAINT "ck_sourcing_prices_period" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" >= "EffectiveFrom");
ALTER TABLE "procurement"."sourcing_prices" ADD CONSTRAINT "ck_sourcing_prices_unit_price" CHECK ("UnitPrice" >= 0);
ALTER TABLE "organization"."internal_people" ADD CONSTRAINT "ck_internal_people_version" CHECK ("Version" >= 1);
ALTER TABLE "procurement"."suppliers" ADD CONSTRAINT "ck_suppliers_lead_score" CHECK ("ExpertLeadTimeScore" IS NULL OR "ExpertLeadTimeScore" BETWEEN 1 AND 10);
ALTER TABLE "procurement"."suppliers" ADD CONSTRAINT "ck_suppliers_quality_score" CHECK ("ExpertQualityScore" IS NULL OR "ExpertQualityScore" BETWEEN 1 AND 10);
ALTER TABLE "procurement"."suppliers" ADD CONSTRAINT "ck_suppliers_version" CHECK ("Version" >= 1);
ALTER TABLE "procurement"."supplier_contacts" ADD CONSTRAINT "ck_supplier_contacts_primary_active" CHECK (NOT "IsPrimary" OR "IsActive");
ALTER TABLE "procurement"."supplier_payment_profiles" ADD CONSTRAINT "ck_supplier_credit" CHECK (("CreditPercent" = 0 AND "CreditDays" IS NULL AND "CreditAnchor" IS NULL) OR ("CreditPercent" > 0 AND "CreditDays" > 0 AND "CreditAnchor" IN ('ORDERED','SHIPPED','WAREHOUSE_RECEIPT')));
ALTER TABLE "procurement"."supplier_payment_profiles" ADD CONSTRAINT "ck_supplier_payment_percentages" CHECK ("AdvancePercent" BETWEEN 0 AND 100 AND "BeforeShipmentPercent" BETWEEN 0 AND 100 AND "CreditPercent" BETWEEN 0 AND 100);
